form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="unassign-editor"><input type="hidden" name="submission_id" value="<?=(int)$s['id']?>"><button>Unassign</button></form><?php endif; ?><?php endif; ?></td><td><?=(int)$s['review_count']?></td><td><a class="button" href="?page=editor-workflow&id=<?=(int)$s['id']?>">View</a></td></tr><?php endforeach; ?></tbody></table><?php elseif($page==='editor-workflow'): $editor=require_login();if(!(has_role($editor,'Editor')||has_role($editor,'Journal Manager')||has_role($editor,'Site Administrator'))){http_response_code(403);exit('Access denied');}$sid=(int)($_GET['id']??0);$q=db()->prepare('SELECT s.*,u.given_name,u.family_name,u.email FROM submissions s JOIN users u ON u.id=s.author_id WHERE s.id=?');$q->execute([$sid]);$paper=$q->fetch();if(!$paper){http_response_code(404);exit('Submission not found');}$tab=$_GET['tab']??strtolower($paper['stage']);if(!in_array($tab,['submission','review','copyediting','production'],true))$tab='submission'; ?>
