</label><input type="number" name="sort_order" min="1" value="<?=count($structuredAuthors)+1?>"><label>Name</label><input name="author_name" required><label>Affiliation</label><input name="affiliation"><label>ORCID</label><input name="orcid" placeholder="0000-0000-0000-0000"><label>Scopus Author ID</label><input name="scopus_id"><button>Add Author</button></form><hr><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="action" value="production-update"><input type="hidden" name="submission_id" value="<?=$sid?>"><label>Production Action</label><select name="production_step"><option>Move to Production</option><option>Publish</option></select><label>Published Issue</label><select name="issue_id"><option value="">Select issue</option><?php $iq=db()->query("SELECT * FROM issues WHERE status='Published' ORDER BY year DESC,volume DESC,number DESC");foreach($iq->fetchAll() as $iss): ?><option value="<?=(int)$iss['id']?>">Vol. <?=(int)$iss['volume']?> No. <?=(int)$iss['number']?> (<?=(int)$iss['year']?>)</option><?php endforeach; ?></select><label>Pages</label><input name="pages" placeholder="1-12"><label>DOI</label><input name="doi"><button>Update Production</button></form></div><?php endif; ?><?php elseif($page==='editor'): $editor=require_login();if(!(has_role($editor,'Editor')||has_role($editor,'Journal Manager')||has_role($editor,'Site Administrator'))){http_response_code(403);exit('Access denied');}$items=db()->query("SELECT s.*,u.given_name,u.family_name,(SELECT COUNT(*) FROM reviews r WHERE r.submission_id=s.id) review_count,(SELECT COUNT(*) FROM reviews r WHERE r.submission_id=s.id AND r.status='Submitted') completed_reviews FROM submissions s JOIN users u ON u.id=s.author_id ORDER BY CASE s.stage WHEN 'Review' THEN 1 WHEN 'Submission' THEN 2 WHEN 'Copyediting' THEN 3 WHEN 'Production' THEN 4 ELSE 5 END,s.updated_at DESC")->fetchAll(); ?>
