<?php elseif($page==='citation-download'): $aid=(int)($_GET['id']??0);$format=strtolower($_GET['format']??'ris');$q=db()->prepare("SELECT s.*,p.issue_label,p.pages,p.doi,p.published_at FROM submissions s JOIN production_items p ON p.submission_id=s.id WHERE s.id=? AND s.status='Published' AND p.published_at IS NOT NULL");$q->execute([$aid]);$ca=$q->fetch();if(!$ca){http_response_code(404);exit('Not Found');}$aq=db()->prepare('SELECT name FROM submission_authors WHERE submission_id=? ORDER BY sort_order,id');$aq->execute([$aid]);$names=array_column($aq->fetchAll(),'name');if(!$names)$names=array_values(array_filter(array_map('trim',preg_split('/;|\band\b/i',$ca['authors']))));$year=substr($ca['published_at'],0,4);$vol='';$num='';if(preg_match('/Vol\.?\s*(\d+).*?No\.?\s*(\d+)/i',$ca['issue_label']??'',$m)){$vol=$m[1];$num=$m[2];}$sp='';$ep='';if(preg_match('/(\d+)\s*[-–]\s*(\d+)/u',$ca['pages']??'',$pm)){$sp=$pm[1];$ep=$pm[2];}$base=rtrim(getenv('APP_URL')?:'', '/');$url=$base.'/?page=article&id='.$aid;$safeKey=preg_replace('/[^A-Za-z0-9]+/','',($names[0]??'Article').$year.'NA'.$aid);if($format==='bibtex'){$out="@article{".$safeKey.",\n  title = {".$ca['title']."},\n  author = {".implode(' and ',$names)."},\n  journal = {".setting('journal_name','Nigerian Affairs')."},\n  year = {".$year."},".($vol?"\n  volume = {".$vol."},":'').($num?"\n  number = {".$num."},":'').($ca['pages']?"\n  pages = {".$ca['pages']."},":'').($ca['doi']?"\n  doi = {".$ca['doi']."},":'')."\n  url = {".$url."}\n}\n";header('Content-Type: application/x-bibtex; charset=utf-8');header('Content-Disposition: attachment; filename="nigerian-affairs-'.$aid.'.bib"');echo $out;exit;}$lines=['TY  - JOUR','TI  - '.$ca['title']];foreach($names as $n)$lines[]='AU  - '.$n;$lines[]='JO  - '.setting('journal_name','Nigerian Affairs');$lines[]='PY  - '.$year;if($vol)$lines[]='VL  - '.$vol;if($num)$lines[]='IS  - '.$num;if($sp)$lines[]='SP  - '.$sp;if($ep)$lines[]='EP  - '.$ep;if($ca['doi'])$lines[]='DO  - '.$ca['doi'];$lines[]='UR  - '.$url;$lines[]='ER  - ';header('Content-Type: application/x-research-info-systems; charset=utf-8');header('Content-Disposition: attachment; filename="nigerian-affairs-'.$aid.'.ris"');echo implode("\r\n",$lines)."\r\n";exit; ?>
