<?php if(!$a): ?><main class="wide content"><h2>Article not found</h2></main><?php else: ?><?php $vol='';$num='';if(preg_match('/Vol\.?\s*(\d+).*?No\.?\s*(\d+)/i',$a['issue_label']??'',$im)){$vol=$im[1];$num=$im[2];}$first='';$last='';if(preg_match('/(\d+)\s*[-–]\s*(\d+)/u',$a['pages']??'',$pm)){$first=$pm[1];$last=$pm[2];}$gqmeta=db()->prepare("SELECT file_path FROM galleys WHERE submission_id=? AND mime_type='application/pdf' ORDER BY id DESC LIMIT 1");$gqmeta->execute([$a['id']]);$pdf=$gqmeta->fetchColumn();$base=rtrim(getenv('APP_URL')?:'', '/');$canonical=$base.'/?page=article&id='.(int)$a['id'];$pdfUrl=$pdf?($base.'/'.ltrim($pdf,'/')):'';$aq=db()->prepare('SELECT * FROM submission_authors WHERE submission_id=? ORDER BY sort_order,id');$aq->execute([$a['id']]);$authorRows=$aq->fetchAll();$citeNames=$authorRows?array_column($authorRows,'name'):array_values(array_filter(array_map('trim',preg_split('/;|\band\b/i',$a['authors']))));$authorText=$citeNames?implode(', ',$citeNames):$a['authors'];$year=substr($a['published_at'],0,4);$apa=$authorText.' ('.$year.'). '.$a['title'].'. '.setting('journal_name','Nigerian Affairs').($vol?', '.$vol.($num?'('.$num.')':''):'').($a['pages']?', '.$a['pages']:'').'.'.($a['doi']?' https://doi.org/'.$a['doi']:'');$mla=$authorText.'. “'.$a['title'].'.” '.setting('journal_name','Nigerian Affairs').($vol?', vol. '.$vol:'').($num?', no. '.$num:'').', '.$year.($a['pages']?', pp. '.$a['pages']:'').'.';$chicago=$authorText.'. “'.$a['title'].'.” '.setting('journal_name','Nigerian Affairs').($vol?' '.$vol:'').($num?', no. '.$num:'').' ('.$year.')'.($a['pages']?': '.$a['pages']:'').'.'; ?>
<head><link rel="canonical" href="<?=e($canonical)?>"><meta name="citation_title" content="<?=e($a['title'])?>"><meta name="citation_journal_title" content="<?=e(setting('journal_name','Nigerian Affairs'))?>"><meta name="citation_publication_date" content="<?=e(substr($a['published_at'],0,10))?>"><?php foreach($citeNames as $ca): ?><meta name="citation_author" content="<?=e($ca)?>"><?php endforeach; ?><?php if($vol): ?><meta name="citation_volume" content="<?=e($vol)?>"><?php endif; ?><?php if($num): ?><meta name="citation_issue" content="<?=e($num)?>"><?php endif; ?><?php if($first): ?><meta name="citation_firstpage" content="<?=e($first)?>"><?php endif; ?><?php if($last): ?><meta name="citation_lastpage" content="<?=e($last)?>"><?php endif; ?><?php if($a['doi']): ?><meta name="citation_doi" content="<?=e($a['doi'])?>"><?php endif; ?><?php if($pdfUrl): ?><meta name="citation_pdf_url" content="<?=e($pdfUrl)?>"><?php endif; ?><meta name="citation_abstract_html_url" content="<?=e($canonical)?>"><meta name="citation_language" content="<?=e($a['language']?:'English')?>"></head>
<main class="wide layout"><section><p><a href="?page=home">Home</a> / <a href="?page=archives">Archives</a> / <a href="?page=current"><?=e($a['issue_label']??'Current Issue')?></a></p><h2><?=e($a['title'])?></h2><?php if($authorRows): ?><div class="article-authors"><?php foreach($authorRows as $au): ?><div class="paper"><strong><?=e($au['name'])?></strong><?php if($au['affiliation']): ?><br><span><?=e($au['affiliation'])?></span><?php endif; ?><?php if($au['orcid']): ?><br><a href="https://orcid.org/<?=e($au['orcid'])?>" target="_blank" rel="noopener"><span aria-hidden="true">iD</span> ORCID: <?=e($au['orcid'])?></a><?php endif; ?><?php if($au['scopus_id']): ?><br><span>Scopus Author ID: <?=e($au['scopus_id'])?></span><?php endif; ?></div><?php endforeach; ?></div><?php else: ?><p><strong><?=e($a['authors'])?></strong></p><?php endif; ?><p><strong>Keywords:</strong> <?=e($a['keywords'])?></p><h3>Abstract</h3><p><?=nl2br(e($a['abstract']))?></p><p><strong>Pages:</strong> <?=e($a['pages']??'')?><?php if($a['doi']): ?><br><strong>DOI:</strong> <a href="https://doi.org/<?=e($a['doi'])?>" target="_blank" rel="noopener"><?=e($a['doi'])?></a><?php endif; ?></p><?php $gq=db()->prepare("SELECT * FROM galleys WHERE submission_id=? ORDER BY id");$gq->execute([$a['id']]);foreach($gq->fetchAll() as $g): ?><p><a class="button" href="<?=e($g['file_path'])?>" target="_blank" rel="noopener">View <?=e($g['label'])?></a></p><?php endforeach; ?><h3>How to Cite</h3><div class="paper"><strong>APA 7th</strong><p><?=e($apa)?></p><details><summary>More Citation Formats</summary><p><strong>MLA</strong><br><?=e($mla)?></p><p><strong>Chicago</strong><br><?=e($chicago)?></p></details><p><a href="?page=citation-download&id=<?=(int)$a['id']?>&format=ris">Download RIS</a> · <a href="?page=citation-download&id=<?=(int)$a['id']?>&format=bibtex">Download BibTeX</a></p></div></section><aside class="public-sidebar"><?php if($pdf): ?><div class="public-sidebox"><h3>Article Access</h3><a class="button" href="<?=e($pdf)?>" target="_blank" rel="noopener">View PDF</a></div><?php endif; ?><div class="public-sidebox"><h3>Share</h3><?=share_links($canonical,$a['title'])?></div><div class="public-sidebox"><h3>Article Details</h3><p><strong>Published</strong><br><?=e(substr($a['published_at'],0,10))?></p><p><strong>Issue</strong><br><?=e($a['issue_label']??'')?></p><p><strong>Section</strong><br><?=e($a['section'])?></p></div><div class="public-sidebox"><h3>Copyright and Licence</h3><p>Copyright © <?=e($year)?> <?=e($authorText)?>.</p><p><a href="https://creativecommons.org/licenses/by/4.0/" target="_blank" rel="license noopener">Creative Commons Attribution 4.0 International License</a></p></div><div class="public-sidebox"><h3>Journal Details</h3><p>Frequency<br><strong><?=e($journalFrequency)?></strong></p><p>Access<br><strong>Open access</strong></p><p>Review<br><strong>Double-blind</strong></p></div></aside></main><?php endif; ?>
<?php elseif($page==='current'): $q=db()->query("SELECT i.id,i.volume,i.number,i.year,i.title,i.description,i.published_at,CONCAT('Vol. ',i.volume,' No. ',i.number,' (',i.year,')') issue_label FROM issues i WHERE i.status='Published' AND EXISTS (SELECT 1 FROM production_items p JOIN submissions s ON s.id=p.submission_id WHERE s.status='Published' AND p.issue_label=CONCAT('Vol. ',i.volume,' No. ',i.number,' (',i.year,')')) ORDER BY i.published_at DESC,i.year DESC,i.volume DESC,i.number DESC LIMIT 1");$issue=$q->fetch();$currentUrl=rtrim(getenv('APP_URL')?:'', '/').'/?page=current';$latestAnnouncement=db()->query("SELECT title,body,published_at FROM announcements WHERE published_at IS NOT NULL ORDER BY published_at DESC LIMIT 1")->fetch(); ?>
